/* ---------- state ---------- */
const KEY="telecom_offers_v1";
let S={lang:null,theme:"auto",showCost:true,favs:[],cmp:[]};
try{const x=JSON.parse(localStorage.getItem(KEY)||"null");if(x)S=Object.assign(S,x);}catch(e){}
if(!S.lang){const n=(navigator.language||"ar").slice(0,2);S.lang=LANGS.some(l=>l[0]===n)?n:"ar";}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}};
const t=k=>(T[S.lang]&&T[S.lang][k])||T.en[k]||k;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const coName=c=>c.n[S.lang]||c.n.en;
const CATS=["cd","fx","dt","vz"];

/* ---------- icon ---------- */
function iconSVG(){
  const arc=r=>{const d=r*.7071;return `<path d="M${256-d} ${330-d}A${r} ${r} 0 0 1 ${256+d} ${330-d}" fill="none" stroke="#fff" stroke-width="34" stroke-linecap="round"/>`;};
  return `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0f766e"/><stop offset="1" stop-color="#14b8a6"/></linearGradient></defs><rect width="512" height="512" rx="112" fill="url(#g)"/>${arc(70)}${arc(130)}${arc(190)}<circle cx="256" cy="330" r="28" fill="#fff"/><rect x="170" y="392" width="172" height="30" rx="15" fill="#fff" opacity=".9"/></svg>`;
}
$("#logo").innerHTML=iconSVG().replace('id="g"','id="g2"').replace('url(#g)','url(#g2)');

/* ---------- formatting ---------- */
const fmtData=d=>{if(d===""||d===0||d==null)return"";if(d==="U")return t("unl");if(d==="1TB")return"1 "+t("tb");return d+" "+t("gb");};
function fmtSocial(s){if(s===""||s===0||s==null)return"";const m=String(s).match(/^(Uc|Us|U|\d+)(\**)$/);if(!m)return esc(s);
  const b=m[1]==="U"?t("unl"):m[1]==="Us"?t("usx"):m[1]==="Uc"?t("uc"):m[1]+" "+t("gb");return b+m[2];}
function fmtCalls(c){if(c==="")return"";const m=String(c).match(/^(U|\d+)([aoil]?)(?:\+(\d+))?(\**)$/);if(!m)return esc(c);
  let s=(m[1]==="U"?t("unl"):m[1]+" "+t("min"));
  if(m[2])s+=" · "+t("sc_"+m[2]);
  if(m[3])s+=" + "+m[3]+" "+t("min")+" "+t("sc_a");
  return s+m[4];}
function fmtVal(v){if(!v)return"";const n=parseInt(v),u={d:0,w:2,m:4}[v.slice(-1)];return n+" "+t("u")[u+(n===1?0:1)];}
const money=n=>n+" "+t("cur");
const dataNum=d=>d==="U"?99999:d==="1TB"?1000:(+d||0);
function offerTitle(o){return o.n||(o.d==="U"?t("unl"):fmtData(o.d));}

/* ---------- data ---------- */
let DATA_INFO={src:"",updated:""};
function setData(obj,info){
  CO=obj.companies||[];ALL.length=0;
  CO.forEach(function(c){CATS.forEach(function(cat){(c.cats[cat]||[]).forEach(function(r,i){
    ALL.push({cid:c.id,cat:cat,i:i,n:r[0],c:r[1],d:r[2],s:r[3],o:r[4],k:r[5],v:r[6]||"",key:[c.id,cat,r[0],r[2],r[6]||"",r[3]].join("|")});});});});
  DATA_INFO=info||{src:"json",updated:obj.updated||""};
}
function xhr(url,cb){
  try{const x=new XMLHttpRequest();x.open("GET",url);x.timeout=20000;
    x.onreadystatechange=function(){if(x.readyState!==4)return;
      if((x.status>=200&&x.status<300)&&x.responseText)cb(null,x.responseText);else cb(new Error("http "+x.status));};
    x.ontimeout=function(){cb(new Error("timeout"));};x.send();}catch(e){cb(e);}
}
function parseCSV(txt){
  const rows=[];let row=[],f="",q=false;
  for(let i=0;i<txt.length;i++){const ch=txt[i];
    if(q){if(ch==='"'){if(txt[i+1]==='"'){f+='"';i++;}else q=false;}else f+=ch;}
    else if(ch==='"')q=true;
    else if(ch===","){row.push(f);f="";}
    else if(ch==="\n"||ch==="\r"){if(ch==="\r"&&txt[i+1]==="\n")i++;row.push(f);f="";if(row.length>1||row[0]!=="")rows.push(row);row=[];}
    else f+=ch;}
  if(f!==""||row.length){row.push(f);rows.push(row);}
  return rows;
}
function applySheet(base,csv){
  const rows=parseCSV(csv);if(rows.length<2)return null;
  const h=rows[0].map(function(x){return x.trim().toLowerCase();});
  const ix=function(n){return h.indexOf(n);};
  const I={co:ix("company"),cat:ix("category"),n:ix("name"),c:ix("calls"),d:ix("data"),s:ix("social"),o:ix("official"),k:ix("price"),v:ix("validity")};
  if(I.co<0||I.cat<0||I.o<0||I.k<0)return null;
  const num=function(x){x=(x||"").trim();return /^\d+(\.\d+)?$/.test(x)?+x:x;};
  const map={};base.companies.forEach(function(c){map[c.id]={};});
  let n=0;
  rows.slice(1).forEach(function(r){
    const id=(r[I.co]||"").trim(),cat=(r[I.cat]||"").trim(),o=parseFloat(r[I.o]),k=parseFloat(r[I.k]);
    if(!map[id]||CATS.indexOf(cat)<0||isNaN(o)||isNaN(k))return;
    (map[id][cat]=map[id][cat]||[]).push([(r[I.n]||"").trim(),(r[I.c]||"").trim(),num(r[I.d]),num(r[I.s]),o,k,(r[I.v]||"").trim()]);n++;});
  if(n<5)return null;
  return {updated:new Date().toISOString().slice(0,10),companies:base.companies.map(function(c){return Object.assign({},c,{cats:map[c.id]});}).filter(function(c){return Object.keys(c.cats).length;})};
}
const CACHE_KEY="toff_data_v2";
function loadData(manual){
  let shown=false;
  if(!manual){try{const c=JSON.parse(localStorage.getItem(CACHE_KEY)||"null");
    if(c&&c.obj&&c.obj.companies){setData(c.obj,c.info);shown=true;route();}}catch(e){}}
  if(!shown&&!manual)$("#view").innerHTML=`<div class="empty">${t("loading")}</div>`;
  const q=function(u){return u+(u.indexOf("?")>-1?"&":"?")+"_="+Date.now();};
  xhr(q(CFG.dataUrl),function(err,txt){
    let base=null;try{base=JSON.parse(txt);}catch(e){}
    if(err||!base||!base.companies){if(!shown)errScreen();else if(manual)toast(t("load_err"));return;}
    const fin=function(obj,info){setData(obj,info);try{localStorage.setItem(CACHE_KEY,JSON.stringify({obj:obj,info:info}));}catch(e){}
      route();if(manual)toast(t("refreshed"));};
    if(CFG.sheetCsv){
      xhr(q(CFG.sheetCsv),function(e2,csv){
        const o=!e2&&applySheet(base,csv);
        if(o)fin(o,{src:"sheet",updated:o.updated});else fin(base,{src:"json",updated:base.updated||""});});
    }else fin(base,{src:"json",updated:base.updated||""});
  });
}
function errScreen(){$("#view").innerHTML=`<div class="empty">⚠️<br>${t("load_err")}<br><br><button class="btn" data-act="retry">${t("retry")}</button></div>`;}
const byId=id=>CO.find(c=>c.id===id);
const isFav=k=>S.favs.includes(k);

/* ---------- render pieces ---------- */
const tile=(c,cls)=>{const src=CFG.logoDir?CFG.logoDir+c.id+".png":"";return `<div class="ic ${src?"lg ":""}${cls||""}" style="background:linear-gradient(135deg,${c.c},${c.c}cc)"><span>${c.l}</span>${src?`<img src="${src}" alt="" onerror="this.parentNode.removeChild(this)">`:""}</div>`;};
function offerCard(o,showCo){
  const c=byId(o.cid),calls=fmtCalls(o.c),soc=fmtSocial(o.s),dat=fmtData(o.d),val=fmtVal(o.v);
  const chips=[calls&&`<span>📞 <b>${t("calls")}:</b> ${calls}</span>`,dat&&`<span>📶 <b>${t("data")}:</b> ${dat}</span>`,soc&&`<span>💬 <b>${t("social")}:</b> ${soc}</span>`].filter(Boolean).join("");
  return `<div class="offer wm"><div class="oh">${showCo?tile(c,"sm"):""}<div class="t"><b>${esc(offerTitle(o))}</b><small>${showCo?esc(coName(c))+" · ":""}${t("cat_"+o.cat)}${val?" · 🕒 "+val:""}</small></div><button class="star ${isFav(o.key)?"on":""}" data-act="fav" data-k="${o.key}" aria-label="save">${isFav(o.key)?"★":"☆"}</button></div>${chips?`<div class="fx">${chips}</div>`:""}<div class="pr"><div><span>${t("official")}</span><b>${money(o.o)}</b></div>${S.showCost?`<div class="c"><span>${t("cost")}</span><b>${money(o.k)}</b></div>`:""}</div><div class="acts2"><button class="w" data-act="wa" data-k="${o.key}">${t("wa_share")}</button><button class="${S.cmp.includes(o.key)?"on":""}" data-act="cmp" data-k="${o.key}">⚖ ${t("cmp")}</button></div></div>`;
}
function sortList(a,mode){a=a.slice();if(mode==="o")a.sort((x,y)=>x.o-y.o);else if(mode==="d")a.sort((x,y)=>dataNum(y.d)-dataNum(x.d));return a;}

/* ---------- views ---------- */
let VS={hv:"",htol:"10",hcat:"all",hsort:"c",pcat:"all",psort:"c",cmode:"price",pv:"",tol:"10",cat:"all",sort:"n",q:"",max:"",sq:"",smax:"",ssort:"o"};
const priceOf=o=>S.showCost?o.k:o.o;
function finderList(v,tol,cat,sort){
  let l=ALL.filter(function(o){return (cat==="all"||o.cat===cat)&&Math.abs(priceOf(o)-v)<=tol;});
  l.sort(function(x,y){
    if(sort==="o")return priceOf(x)-priceOf(y)||dataNum(y.d)-dataNum(x.d);
    if(sort==="d")return dataNum(y.d)-dataNum(x.d)||priceOf(x)-priceOf(y);
    return Math.abs(priceOf(x)-v)-Math.abs(priceOf(y)-v)||dataNum(y.d)-dataNum(x.d);});
  return l.slice(0,40);
}
function filtUI(p){
  const cur=VS[p+"cat"],sv=VS[p+"sort"];
  return `<div class="chips">${["all","cd","fx","dt","vz"].map(function(k){return `<button class="chip ${cur===k?"on":""}" data-act="fcat" data-p="${p}" data-v="${k}">${t("cat_"+k)}</button>`;}).join("")}</div><div class="tools"><select data-act="fsort" data-p="${p}">${[["c",t("s_c")],["o",t("s_o")],["d",t("s_d")]].map(function(x){return `<option value="${x[0]}" ${sv===x[0]?"selected":""}>${x[1]}</option>`;}).join("")}</select></div>`;
}
function homeBody(){
  const v=parseFloat(VS.hv);
  if(!(v>0))return `<div class="grid">${CO.map(c=>{const n=CATS.reduce((a,k)=>a+(c.cats[k]||[]).length,0);return `<div class="co" data-act="open" data-id="${c.id}">${tile(c)}<b>${esc(coName(c))}</b><small>${n} ${t("offers")}</small></div>`;}).join("")}</div>`;
  const l=finderList(v,+VS.htol,VS.hcat,VS.hsort),F=filtUI("h");
  if(!l.length)return F+`<div class="empty">${t("nores")}</div>`;
  return F+`<p class="sub">${l.length} ${t("offers")} ${t("near")} ${v} ${t("cur")}</p>${l.map(o=>offerCard(o,true)).join("")}<div class="acts2"><button class="on" data-act="cmpthese">⚖ ${t("cmp_these")}</button></div>`;
}
function vHome(){
  return `<h2>${t("app")}</h2><p class="sub">${t("tag")}</p>
  <div class="sec" style="padding:12px 14px"><b>${t("need_price")}</b><div class="tools" style="margin:8px 0 2px"><input id="hpv" type="number" inputmode="decimal" placeholder="0" value="${esc(VS.hv)}"><select id="htol">${[["0",t("tol_exact")],["10","± 10"],["20","± 20"],["30","± 30"]].map(x=>`<option value="${x[0]}" ${VS.htol===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></div></div>
  <div id="hbody">${homeBody()}</div>`;
}
function vCompany(id){
  const c=byId(id);if(!c)return vHome();
  const cats=CATS.filter(k=>c.cats[k]);
  if(VS.cat!=="all"&&!cats.includes(VS.cat))VS.cat="all";
  let list=ALL.filter(o=>o.cid===id&&(VS.cat==="all"||o.cat===VS.cat));
  list=sortList(list,VS.sort);
  const note=c.notes&&(c.notes[S.lang]||c.notes.en);
  return `<div class="bar"><button class="back" data-act="home">${RTL[S.lang]?"→":"←"}</button>${tile(c,"sm")}<h2>${esc(coName(c))}</h2></div>
  <div class="chips">${["all",...cats].map(k=>`<button class="chip ${VS.cat===k?"on":""}" data-act="cat" data-v="${k}">${t("cat_"+k)}</button>`).join("")}</div>
  <div class="tools"><select data-act="sort"><option value="n" ${VS.sort==="n"?"selected":""}>${t("s_n")}</option><option value="o" ${VS.sort==="o"?"selected":""}>${t("s_o")}</option><option value="d" ${VS.sort==="d"?"selected":""}>${t("s_d")}</option></select></div>
  <div id="list">${list.map(o=>offerCard(o)).join("")}</div>${note?`<div class="note">${esc(note)}</div>`:""}`;
}
function searchList(){
  let l=ALL.filter(o=>{const c=byId(o.cid),q=VS.sq.trim().toLowerCase();
    if(q){const hay=(coName(c)+" "+c.n.en+" "+offerTitle(o)+" "+o.d+" "+o.o+" "+o.k).toLowerCase();if(!hay.includes(q))return false;}
    if(VS.smax!==""&&o.o>+VS.smax)return false;return true;});
  l=sortList(l,VS.ssort);
  return l.length?l.map(o=>offerCard(o,true)).join(""):`<div class="empty">${t("nores")}</div>`;
}
function vSearch(){
  return `<h2>${t("search")}</h2><div class="tools"><input id="sq" type="search" placeholder="${t("sph")}" value="${esc(VS.sq)}"><input id="smax" type="number" inputmode="numeric" placeholder="${t("budget")}" value="${esc(VS.smax)}" style="max-width:130px"><select id="ssort"><option value="o" ${VS.ssort==="o"?"selected":""}>${t("s_o")}</option><option value="d" ${VS.ssort==="d"?"selected":""}>${t("s_d")}</option></select></div><div id="slist">${searchList()}</div>`;
}
function vFavs(){
  const l=ALL.filter(o=>isFav(o.key));
  return `<h2>${t("favs")}</h2>${l.length?l.map(o=>offerCard(o,true)).join(""):`<div class="empty">☆<br>${t("fav_empty")}</div>`}`;
}
function vSettings(){
  const th=(k,l)=>`<button class="${S.theme===k?"on":""}" data-act="theme" data-v="${k}">${l}</button>`;
  return `<h2>${t("settings")}</h2>
  <div class="sec"><div class="row"><span>${t("theme")}</span><div class="seg">${th("auto",t("th_auto"))}${th("light",t("th_light"))}${th("dark",t("th_dark"))}</div></div>
  <div class="row"><span>${t("showcost")}</span><button class="sw ${S.showCost?"on":""}" data-act="cost" aria-label="${t("showcost")}"></button></div></div>
  <div class="sec"><h3>${t("ver")}</h3><div class="row"><span>${t("ver")} <b dir="ltr">${APP_VERSION}</b></span><button class="btn" data-act="check" id="chkBtn">${t("update")}</button></div></div>
  <div class="sec"><h3>${t("prices")}</h3><div class="row"><span><b dir="ltr">${esc(DATA_INFO.updated||"-")}</b></span><button class="btn g" data-act="refreshp">${t("refreshp")}</button></div></div>
  <div class="sec"><h3>${t("backup")}</h3><div class="row"><button class="btn g" data-act="export">${t("export")}</button><button class="btn g" data-act="import">${t("import")}</button></div><input type="file" id="impFile" accept="application/json,.json" hidden></div>
  <div class="sec"><h3>${t("pages")}</h3>${["terms","privacy","about","contact"].map(p=>`<button class="lnk" data-act="page" data-v="${p}"><span>${t(p)}</span><span>${RTL[S.lang]?"‹":"›"}</span></button>`).join("")}</div>`;
}
function vPage(p){
  const txt=(PAGES[S.lang]||PAGES.en)[p]||PAGES.en[p];
  let extra="";
  if(p==="contact"){const b=[];if(CONTACT.whatsapp)b.push(`<a class="btn" style="text-decoration:none" href="https://wa.me/${CONTACT.whatsapp}" target="_blank" rel="noopener">${t("wa")}</a>`);
    if(CONTACT.email)b.push(`<a class="btn g" style="text-decoration:none" href="mailto:${CONTACT.email}">${t("mail")}</a>`);
    if(b.length)extra=`<div class="acts" style="display:flex">${b.join("")}</div>`;}
  return `<div class="bar"><button class="back" data-act="settingsGo">${RTL[S.lang]?"→":"←"}</button><h2>${t(p)}</h2></div><div class="sec pg"><p>${esc(txt)}</p>${extra}</div>`;
}


function callsNum(c){const m=String(c).match(/^(U|\d+)/);return m?(m[1]==="U"?99999:+m[1]):0;}
function vManual(){
  const sel=S.cmp.map(k=>ALL.find(o=>o.key===k)).filter(Boolean);
  if(!VS.cc)VS.cc=CO[0].id;
  const pk=ALL.filter(o=>o.cid===VS.cc);
  const pick=`<div class="tools"><select data-act="cco">${CO.map(c=>`<option value="${c.id}" ${c.id===VS.cc?"selected":""}>${esc(coName(c))}</option>`).join("")}</select><select id="cpk">${pk.map(o=>`<option value="${o.key}">${esc(offerTitle(o))} · ${fmtData(o.d)||""} · ${o.o}</option>`).join("")}</select><button class="btn" data-act="cmpadd" style="flex:none">${t("add")}</button></div>`;
  if(!sel.length)return `${pick}<div class="empty">⚖<br>${t("cmp_empty")}</div>`;
  const P=o=>S.showCost?o.k:o.o,pg=o=>{const d=dataNum(o.d);return d&&d<1000?P(o)/d:null;};
  const best=(fn,dir)=>{const v=sel.map(fn).filter(x=>x!=null&&x>0);return v.length>1?(dir>0?Math.max(...v):Math.min(...v)):null;};
  const bp=best(P,-1),bd=best(o=>dataNum(o.d),1),bc=best(o=>callsNum(o.c),1),bg=best(pg,-1);
  const row=(lab,fn,cls)=>`<tr><td>${lab}</td>${sel.map(o=>`<td class="${cls?cls(o):""}">${fn(o)||"–"}</td>`).join("")}</tr>`;
  const tbl=`<div class="cmpw wm"><table class="cmp"><tr><th></th>${sel.map(o=>{const c=byId(o.cid);return `<th>${tile(c,"sm")}${esc(coName(c))}<br><small>${esc(offerTitle(o))}</small><br><button class="rm" data-act="cmp" data-k="${o.key}">✕</button></th>`;}).join("")}</tr>
  ${row(t("calls"),o=>fmtCalls(o.c),o=>bc!=null&&callsNum(o.c)===bc?"best":"")}
  ${row(t("data"),o=>fmtData(o.d),o=>bd!=null&&dataNum(o.d)===bd?"best":"")}
  ${row(t("social"),o=>fmtSocial(o.s))}
  ${row(t("valid"),o=>fmtVal(o.v))}
  ${row(t("official"),o=>money(o.o))}
  ${S.showCost?row(t("cost"),o=>money(o.k),o=>bp!=null&&o.k===bp?"best":""):""}
  ${row(t("pergb"),o=>{const g=pg(o);return g?g.toFixed(2)+" "+t("cur"):"";},o=>{const g=pg(o);return bg!=null&&g&&Math.abs(g-bg)<1e-9?"best":"";})}
  </table></div><p class="sub" style="margin-top:8px">${t("cmp_hint")}</p><div class="acts2"><button data-act="cmpclear">${t("cmp_clear")}</button></div>`;
  return `${pick}${tbl}`;
}
function priceResults(){
  const v=parseFloat(VS.pv);if(!(v>0))return `<div class="empty">💰<br>${t("price_ph")}</div>`;
  const l=finderList(v,+VS.tol,VS.pcat,VS.psort),F=filtUI("p");
  if(!l.length)return F+`<div class="empty">${t("nores")}</div>`;
  const pg=o=>{const d=dataNum(o.d);return d&&d<1000?priceOf(o)/d:null;};
  const mx=fn=>Math.max(...l.map(fn)),mn=fn=>{const x=l.map(fn).filter(z=>z);return x.length?Math.min(...x):null;};
  const bd=mx(o=>dataNum(o.d)),bc=mx(o=>callsNum(o.c)),bg=mn(pg);
  const rows=l.map(o=>{const c=byId(o.cid),g=pg(o);return `<tr><td>${tile(c,"sm")}<b>${esc(coName(c))}</b><br><small>${esc(offerTitle(o))}</small></td>
   <td class="${callsNum(o.c)===bc&&l.length>1?"best":""}">${fmtCalls(o.c)||"–"}</td><td class="${dataNum(o.d)===bd&&l.length>1?"best":""}">${fmtData(o.d)||"–"}</td><td>${fmtSocial(o.s)||"–"}</td><td>${fmtVal(o.v)||"–"}</td><td>${money(o.o)}</td>${S.showCost?`<td><b>${money(o.k)}</b></td>`:""}<td class="${g&&bg!=null&&Math.abs(g-bg)<1e-9&&l.length>1?"best":""}">${g?g.toFixed(2)+" "+t("cur"):"–"}</td></tr>`;}).join("");
  return F+`<p class="sub">${l.length} ${t("offers")} ${t("near")} ${v} ${t("cur")}</p><div class="cmpw wm"><table class="cmp"><tr><th>${t("pick_pk")}</th><th>${t("calls")}</th><th>${t("data")}</th><th>${t("social")}</th><th>${t("valid")}</th><th>${t("official")}</th>${S.showCost?`<th>${t("cost")}</th>`:""}<th>${t("pergb")}</th></tr>${rows}</table></div><p class="sub" style="margin-top:8px">${t("cmp_hint")}</p>`;
}
function vPrice(){
  return `<div class="tools"><input id="pv" type="number" inputmode="decimal" placeholder="${t("price_ph")}" value="${esc(VS.pv)}"><select id="ptol">${[["0",t("tol_exact")],["10","± 10"],["20","± 20"],["30","± 30"]].map(x=>`<option value="${x[0]}" ${VS.tol===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></div><div id="pres">${priceResults()}</div>`;
}
function vCompare(){
  const m=VS.cmode==="manual";
  return `<h2>${t("cmp")}</h2><div class="chips"><button class="chip ${m?"":"on"}" data-act="cmode" data-v="price">${t("cmp_byprice")}</button><button class="chip ${m?"on":""}" data-act="cmode" data-v="manual">${t("cmp_manual")}</button></div>${m?vManual():vPrice()}`;
}
function waText(o){
  const c=byId(o.cid),L=[`📱 ${t("brand")}`,`${coName(c)} - ${offerTitle(o)}`];
  const calls=fmtCalls(o.c),dat=fmtData(o.d),soc=fmtSocial(o.s),val=fmtVal(o.v);
  if(calls)L.push(`📞 ${t("calls")}: ${calls}`);if(dat)L.push(`📶 ${t("data")}: ${dat}`);if(soc)L.push(`💬 ${t("social")}: ${soc}`);if(val)L.push(`🕒 ${val}`);
  L.push(`💰 ${t(S.showCost?"cost":"official")}: ${money(S.showCost?o.k:o.o)}`);
  L.push(cleanUrl());return L.join("\n");
}
function openWA(o){const a=document.createElement("a");a.href="https://wa.me/?text="+encodeURIComponent(waText(o));a.target="_blank";a.rel="noopener";document.body.appendChild(a);a.click();a.remove();}

/* ---------- router ---------- */
function route(){
  const h=location.hash.slice(1)||"home",[a,b]=h.split("/");
  let html,tab=a;
  if(a==="c"){html=vCompany(b);tab="home";}
  else if(a==="p"){html=vPage(b);tab="settings";}
  else if(a==="search")html=vSearch();
  else if(a==="favs"){html=vFavs();tab="";}
  else if(a==="compare")html=vCompare();
  else if(a==="settings")html=vSettings();
  else{html=vHome();tab="home";}
  $("#view").innerHTML=html;
  $("#nav").innerHTML=[["home","🏠",t("home")],["search","🔍",t("search")],["compare","⚖️",t("cmp")],["settings","⚙️",t("settings")]].map(x=>`<button class="${tab===x[0]?"on":""}" data-act="nav" data-v="${x[0]}"><i>${x[1]}</i>${x[2]}</button>`).join("");
  window.scrollTo(0,0);
}
const go=h=>{if(location.hash==="#"+h)route();else location.hash=h;};
window.addEventListener("hashchange",route);

/* ---------- theme / lang ---------- */
const mq=window.matchMedia("(prefers-color-scheme: dark)");
function applyTheme(){const eff=S.theme==="auto"?(mq.matches?"dark":"light"):S.theme;
  document.documentElement.setAttribute("data-theme",eff);
  const m=document.querySelector('meta[name=theme-color]');if(m)m.content=eff==="dark"?"#14201e":"#0f766e";}
if(mq.addEventListener)mq.addEventListener("change",applyTheme);else if(mq.addListener)mq.addListener(applyTheme);
function setWM(){const s=`<svg xmlns="http://www.w3.org/2000/svg" width="220" height="120"><text x="110" y="64" text-anchor="middle" font-family="sans-serif" font-size="15" font-weight="700" fill="#7f8f8a" fill-opacity=".22" transform="rotate(-22 110 60)">${esc(t("brand"))}</text></svg>`;
  document.documentElement.style.setProperty("--wm",`url("data:image/svg+xml;utf8,${encodeURIComponent(s)}")`);}
function renderLangBar(){$("#langbar").innerHTML=LANGS.map(l=>`<button class="${l[0]===S.lang?"on":""}" data-act="setlang" data-v="${l[0]}">${l[1]}</button>`).join("");}
function applyLang(){setWM();renderLangBar();const d=document.documentElement;d.lang=S.lang;d.dir=RTL[S.lang]?"rtl":"ltr";
  document.title=t("app");$("#appTitle").textContent=t("app");$("#instTxt").textContent=t("install");
  $("#bnMsg").textContent=t("newver");$("#bnYes").textContent=t("updnow");$("#bnNo").textContent=t("later");}

/* ---------- modal / toast ---------- */
function modal(html){closeModal();const d=document.createElement("div");d.className="ov";d.id="ov";
  d.innerHTML=`<div class="md">${html}</div>`;d.addEventListener("click",e=>{if(e.target===d)closeModal();});document.body.appendChild(d);}
function closeModal(){const o=$("#ov");if(o)o.remove();}
let tt;function toast(m){const e=$("#toast");e.textContent=m;e.style.display="block";clearTimeout(tt);tt=setTimeout(()=>e.style.display="none",2200);}

/* ---------- install ---------- */
let deferred=null;
const installed=()=>matchMedia("(display-mode: standalone)").matches||navigator.standalone===true||localStorage.getItem("toff_installed")==="1";
function syncInstall(){$("#instBtn").style.display=installed()?"none":"";}
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferred=e;syncInstall();});
window.addEventListener("appinstalled",()=>{try{localStorage.setItem("toff_installed","1");}catch(e){}deferred=null;syncInstall();});
function doInstall(){
  if(deferred){deferred.prompt();Promise.resolve(deferred.userChoice).catch(function(){}).then(function(){deferred=null;});return;}
  modal(`<h3>${t("install")}</h3><p>${t("ios")}</p><p>${t("and")}</p><div class="acts"><button class="btn g" data-act="qr">▦ QR</button><button class="btn" data-act="close">${t("close")}</button></div>`);
}

/* ---------- QR / share ---------- */
function cleanUrl(){return location.href.split("#")[0];}
function showQR(){
  const u=cleanUrl(),local=!/^https:/.test(u)||/localhost|127\.0\.0\.1|192\.168\./.test(u);
  modal(`<h3>${t("qr_title")}</h3><canvas id="qrc"></canvas><p>${t("qr_hint")}</p>${local?`<p style="color:var(--gold)">${t("qr_warn")}</p>`:""}<p style="margin-bottom:0">${t("link")}</p><input id="qrurl" value="${esc(u)}"><div class="acts"><button class="btn g" data-act="copy">${t("copy")}</button><button class="btn" data-act="close">${t("close")}</button></div>`);
  const draw=()=>{const ok=qrDraw($("#qrc"),$("#qrurl").value,260);if(!ok){const c=$("#qrc");c.width=c.height=1;toast(t("nolink"));}};
  draw();$("#qrurl").addEventListener("input",draw);
}
function shareApp(){
  const u=cleanUrl(),d={title:t("app"),text:t("share_text"),url:u};
  if(navigator.share){navigator.share(d).catch(function(e){if(!(e&&e.name==="AbortError"))copyText(u);});return;}
  copyText(u);
}
function copyText(x){(navigator.clipboard?navigator.clipboard.writeText(x):Promise.reject()).then(()=>toast(t("copied")),()=>{
  const i=document.createElement("input");i.value=x;document.body.appendChild(i);i.select();try{i.setSelectionRange(0,9999);document.execCommand("copy");toast(t("copied"));}catch(e){}i.remove();});}

/* ---------- backup ---------- */
function exportBackup(){
  const b=new Blob([JSON.stringify({app:"telecom-offers",v:1,lang:S.lang,theme:S.theme,showCost:S.showCost,favs:S.favs,cmp:S.cmp},null,1)],{type:"application/json"});
  const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="telecom-offers-backup.json";document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000);
}
function importBackup(f){
  const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(x.app!=="telecom-offers")throw 0;
    if(LANGS.some(l=>l[0]===x.lang))S.lang=x.lang;if(["auto","light","dark"].includes(x.theme))S.theme=x.theme;
    S.showCost=x.showCost!==false;S.favs=Array.isArray(x.favs)?x.favs.filter(k=>ALL.some(o=>o.key===k)):[];S.cmp=Array.isArray(x.cmp)?x.cmp.filter(k=>ALL.some(o=>o.key===k)).slice(0,4):[];
    save();applyTheme();applyLang();route();toast(t("imported"));}catch(e){toast(t("bad"));}};r.readAsText(f);
}

/* ---------- updates ---------- */
const newer=(a,b)=>{const x=a.split(".").map(Number),y=b.split(".").map(Number);for(let i=0;i<3;i++){if((x[i]||0)>(y[i]||0))return true;if((x[i]||0)<(y[i]||0))return false;}return false;};
let latest=null;
function checkUpdate(manual){
  const btn=$("#chkBtn");if(manual&&btn)btn.textContent=t("checking");
  const fin=function(){if(manual&&$("#chkBtn"))$("#chkBtn").textContent=t("update");};
  try{const x=new XMLHttpRequest(),u=cleanUrl();
    x.open("GET",u+(u.indexOf("?")>-1?"&":"?")+"_="+Date.now());
    x.onreadystatechange=function(){if(x.readyState!==4)return;
      const m=(x.responseText||"").match(/APP_VERSION\s*=\s*"([\d.]+)"/);
      if(m&&newer(m[1],APP_VERSION)){latest=m[1];$("#banner").style.display="flex";if(manual)toast(t("newver"));}
      else if(manual)toast(t("uptodate"));
      fin();};
    x.send();}
  catch(e){if(manual)toast(t("uptodate"));fin();}
}
function applyUpdate(){
  const go2=function(){location.replace(cleanUrl().split("?")[0]+"?v="+(latest||Date.now())+location.hash);};
  const tasks=[];
  try{if("serviceWorker"in navigator)tasks.push(navigator.serviceWorker.getRegistrations().then(function(rs){return Promise.all(rs.map(function(r){return r.unregister();}));}));
    if(window.caches)tasks.push(caches.keys().then(function(ks){return Promise.all(ks.map(function(k){return caches.delete(k);}));}));}catch(e){}
  Promise.all(tasks).then(go2,go2);
}

/* ---------- events ---------- */
document.addEventListener("click",e=>{
  const el=e.target.closest("[data-act]");if(!el)return;const a=el.dataset.act,v=el.dataset.v;
  if(a==="home")go("home");
  else if(a==="nav")go(v);
  else if(a==="open"){VS.cat="all";VS.sort="n";go("c/"+el.dataset.id);}
  else if(a==="cat"){VS.cat=v;route();}
  else if(a==="fav"){const k=el.dataset.k,i=S.favs.indexOf(k);if(i<0)S.favs.push(k);else S.favs.splice(i,1);save();
    if(location.hash==="#favs")route();else{el.classList.toggle("on",i<0);el.textContent=i<0?"★":"☆";}}
  else if(a==="theme"){S.theme=v;save();applyTheme();route();}
  else if(a==="cost"){S.showCost=!S.showCost;save();route();}
  else if(a==="setlang"){S.lang=v;save();closeModal();applyLang();route();}
  else if(a==="favsGo")go("favs");
  else if(a==="cmode"){VS.cmode=v;route();}
  else if(a==="cmpthese"){VS.pv=VS.hv;VS.tol=VS.htol;VS.cmode="price";go("compare");}
  else if(a==="wa"){const o=ALL.find(x=>x.key===el.dataset.k);if(o)openWA(o);}
  else if(a==="cmp"){const k=el.dataset.k,i=S.cmp.indexOf(k);
    if(i>=0)S.cmp.splice(i,1);else if(S.cmp.length>=4){toast(t("cmp_max"));return;}else S.cmp.push(k);
    save();if(location.hash.slice(1)==="compare")route();else el.classList.toggle("on",i<0);}
  else if(a==="cmpadd"){const k=$("#cpk")&&$("#cpk").value;if(k&&!S.cmp.includes(k)){if(S.cmp.length>=4){toast(t("cmp_max"));return;}S.cmp.push(k);save();route();}}
  else if(a==="cmpclear"){S.cmp=[];save();route();}
  else if(a==="qr")showQR();
  else if(a==="share")shareApp();
  else if(a==="install")doInstall();
  else if(a==="copy")copyText($("#qrurl")?$("#qrurl").value:cleanUrl());
  else if(a==="close")closeModal();
  else if(a==="export")exportBackup();
  else if(a==="import")$("#impFile").click();
  else if(a==="page")go("p/"+v);
  else if(a==="settingsGo")go("settings");
  else if(a==="check")checkUpdate(true);
  else if(a==="retry")loadData(false);
  else if(a==="fcat"){VS[el.dataset.p+"cat"]=v;if(el.dataset.p==="h")$("#hbody").innerHTML=homeBody();else $("#pres").innerHTML=priceResults();}
  else if(a==="refreshp")loadData(true);
  else if(a==="doUpdate")applyUpdate();
  else if(a==="bnLater")$("#banner").style.display="none";
});
document.addEventListener("change",e=>{
  if(e.target.id==="impFile"&&e.target.files[0])importBackup(e.target.files[0]);
  if(e.target.dataset&&e.target.dataset.act==="sort"){VS.sort=e.target.value;route();}
  if(e.target.dataset&&e.target.dataset.act==="fsort"){const p=e.target.dataset.p;VS[p+"sort"]=e.target.value;if(p==="h")$("#hbody").innerHTML=homeBody();else $("#pres").innerHTML=priceResults();}
  if(e.target.dataset&&e.target.dataset.act==="cco"){VS.cc=e.target.value;route();}
  if(e.target.id==="htol"){VS.htol=e.target.value;$("#hbody").innerHTML=homeBody();}
  if(e.target.id==="ptol"){VS.tol=e.target.value;$("#pres").innerHTML=priceResults();}
  if(e.target.id==="ssort"){VS.ssort=e.target.value;$("#slist").innerHTML=searchList();}
});
document.addEventListener("input",e=>{
  if(e.target.id==="sq"){VS.sq=e.target.value;$("#slist").innerHTML=searchList();}
  if(e.target.id==="hpv"){VS.hv=e.target.value;$("#hbody").innerHTML=homeBody();}
  if(e.target.id==="pv"){VS.pv=e.target.value;$("#pres").innerHTML=priceResults();}
  if(e.target.id==="smax"){VS.smax=e.target.value;$("#slist").innerHTML=searchList();}
});

/* ---------- start ---------- */
applyTheme();applyLang();syncInstall();
loadData(false);
window.addEventListener("load",function(){
  if("serviceWorker"in navigator&&/^https?:/.test(location.protocol)){navigator.serviceWorker.register("sw.js?v="+APP_VERSION).catch(function(){});}
  setTimeout(function(){checkUpdate(false);},2500);
});
